style.css:
@-moz-document domain("wattpad.com") {
body, html {
    background-color: #ffc4c4 !important;
    color: #3a3a3a !important;
  }

  header, nav, footer, .site-header, .story-tools-bar, .story-header, .header-container {
    background-color: #ff9faa !important;
    color: #fff !important;
    border: none !important;
  }

  .container, .main-container, .main-content, .panel, .story-info, .story-container, .story-page, .story-text, .reading-page, .reading-container, .story-body {
    background-color: #ffe2e2 !important;
    color: #3a3a3a !important;
    border-radius: 8px !important;
    border: none !important;
  }

  .story-body p {
    background-color: #ffe2e2 !important;
    color: #2e2e2e !important;
  }

  .page, .content, .wrapper, .content-container, .reader-container {
    background-color: #ffc4c4 !important;
  }

  a, .story-title, .story-author, .nav-link, .panel-title {
    color: #b4445c !important;
  }

  button, .btn, .btn-primary, .btn-read, .btn-follow {
    background-color: #ff7d7d !important;
    color: #fff !important;
    border: none !important;
  }

  button:hover, .btn:hover {
    background-color: #ff9e9e !important;
  }

  .overlay, .backdrop {
    background-color: transparent !important;
  }

  * {
    box-shadow: none !important;
    border-color: transparent !important;
  }
}
